package record

// Record is an ordered string-to-string record.
// Order preserves the first-seen field order for the record.
type Record struct {
	Order   []string
	Values  map[string]string
	InputRow int
}

func New() *Record {
	return &Record{
		Order:  []string{},
		Values: map[string]string{},
	}
}

func (r *Record) Set(key, val string) {
	if _, ok := r.Values[key]; !ok {
		r.Order = append(r.Order, key)
	}
	r.Values[key] = val
}

func (r *Record) Get(key string) (string, bool) {
	v, ok := r.Values[key]
	return v, ok
}

func (r *Record) Has(key string) bool {
	_, ok := r.Values[key]
	return ok
}

func (r *Record) Copy() *Record {
	nr := New()
	nr.InputRow = r.InputRow
	for _, k := range r.Order {
		nr.Set(k, r.Values[k])
	}
	return nr
}
