type yamlLine struct {
	indent int
	text   string
}

func parseYAML(data []byte) (interface{}, error) {
	lines := []yamlLine{}
	scanner := bufio.NewScanner(bytes.NewReader(data))
	for scanner.Scan() {
		raw := scanner.Text()
		line := stripComment(raw)
		if strings.TrimSpace(line) == "" {
			continue
		}
		indent := 0
		for indent < len(line) && line[indent] == ' ' {
			indent++
		}
		if indent < len(line) && line[indent] == '\t' {
			return nil, fmt.Errorf("tabs are not allowed for indentation")
		}
		text := strings.TrimRight(line[indent:], " \t")
		lines = append(lines, yamlLine{indent: indent, text: text})
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	if len(lines) == 0 {
		return nil, nil
	}
	val, _, err := parseBlock(lines, 0, lines[0].indent)
	return val, err
}

func parseBlock(lines []yamlLine, start, indent int) (interface{}, int, error) {
	if start >= len(lines) {
		return nil, start, nil
	}
	if lines[start].indent < indent {
		return nil, start, nil
	}
	if isSequenceLine(lines[start].text) {
		return parseSequence(lines, start, indent)
	}
	return parseMapping(lines, start, indent)
}

func isSequenceLine(text string) bool {
	return text == "-" || strings.HasPrefix(text, "- ")
}

func parseSequence(lines []yamlLine, start, indent int) (interface{}, int, error) {
	items := []interface{}{}
	i := start
	for i < len(lines) {
		if lines[i].indent < indent {
			break
		}
		if lines[i].indent > indent {
			return nil, i, fmt.Errorf("unexpected indentation in sequence")
		}
		if !isSequenceLine(lines[i].text) {
			break
		}

		content := strings.TrimSpace(strings.TrimPrefix(lines[i].text, "-"))
		if content == "" {
			childIndent := indent + 2
			if i+1 < len(lines) && lines[i+1].indent > indent {
				childIndent = lines[i+1].indent
			}
			val, next, err := parseBlock(lines, i+1, childIndent)
			if err != nil {
				return nil, 0, err
			}
			items = append(items, val)
			i = next
			continue
		}

		if strings.HasPrefix(content, "[") || strings.HasPrefix(content, "{") {
			val, err := parseFlow(content)
			if err != nil {
				return nil, 0, err
			}
			items = append(items, val)
			i++
			continue
		}

		if isMappingLine(content) {
			effIndent := indent + 1
			prefix := strings.TrimPrefix(lines[i].text, "-")
			effIndent = indent + 1 + (len(prefix) - len(strings.TrimLeft(prefix, " ")))
			sublines := []yamlLine{{indent: effIndent, text: strings.TrimSpace(content)}}
			j := i + 1
			for j < len(lines) && lines[j].indent >= effIndent {
				sublines = append(sublines, lines[j])
				j++
			}
			val, _, err := parseMapping(sublines, 0, effIndent)
			if err != nil {
				return nil, 0, err
			}
			items = append(items, val)
			i = j
			continue
		}

		items = append(items, parseScalar(content))
		i++
	}
	return items, i, nil
}

func parseMapping(lines []yamlLine, start, indent int) (map[string]interface{}, int, error) {
	m := map[string]interface{}{}
	i := start
	for i < len(lines) {
		if lines[i].indent < indent {
			break
		}
		if lines[i].indent > indent {
			return nil, i, fmt.Errorf("unexpected indentation in mapping")
		}
		if isSequenceLine(lines[i].text) {
			break
		}

		key, val, err := splitKeyValue(lines[i].text)
		if err != nil {
			return nil, i, err
		}

		if val == "" {
			if i+1 < len(lines) {
				next := lines[i+1]
				if next.indent > indent || (next.indent == indent && isSequenceLine(next.text)) {
					child, next2, err := parseBlock(lines, i+1, next.indent)
					if err != nil {
						return nil, 0, err
					}
					m[key] = child
					i = next2
					continue
				}
			}
			m[key] = nil
			i++
			continue
		}

		if strings.HasPrefix(val, "[") || strings.HasPrefix(val, "{") {
			v, err := parseFlow(val)
			if err != nil {
				return nil, 0, err
			}
			m[key] = v
			i++
			continue
		}

		m[key] = parseScalar(val)
		i++
	}
	return m, i, nil
}

func isMappingLine(text string) bool {
	_, _, err := splitKeyValue(text)
	return err == nil
}

func splitKeyValue(text string) (string, string, error) {
	if len(text) > 0 && (text[0] == '"' || text[0] == '\'') {
		quote := text[0]
		i := 1
		for i < len(text) {
			if text[i] == quote {
				if quote == '\'' && i+1 < len(text) && text[i+1] == '\'' {
					i += 2
					continue
				}
				if quote == '"' && i > 0 && text[i-1] == '\\' {
					i++
					continue
				}
				break
			}
			i++
		}
		if i >= len(text) {
			return "", "", fmt.Errorf("unterminated quoted key")
		}
		key := parseScalar(text[:i+1])
		rest := strings.TrimLeft(text[i+1:], " \t")
		if !strings.HasPrefix(rest, ":") {
			return "", "", fmt.Errorf("expected colon after key")
		}
		rest = rest[1:]
		rest = strings.TrimLeft(rest, " \t")
		return key, rest, nil
	}

	for i := 0; i < len(text); i++ {
		if text[i] == ':' {
			if i+1 >= len(text) {
				return parseScalar(strings.TrimSpace(text[:i])), "", nil
			}
			if text[i+1] == ' ' || text[i+1] == '\t' {
				return parseScalar(strings.TrimSpace(text[:i])), strings.TrimSpace(text[i+1:]), nil
			}
		}
	}
	return "", "", fmt.Errorf("expected mapping key: %q", text)
}

func parseScalar(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		if q, err := strconv.Unquote(s); err == nil {
			return q
		}
		return s[1 : len(s)-1]
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return strings.ReplaceAll(s[1:len(s)-1], "''", "'")
	}
	return s
}

func stripComment(line string) string {
	inSingle := false
	inDouble := false
	for i := 0; i < len(line); i++ {
		c := line[i]
		switch c {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case '#':
			if !inSingle && !inDouble && (i == 0 || line[i-1] == ' ' || line[i-1] == '\t') {
				return line[:i]
			}
		}
	}
	return line
}

func parseFlow(s string) (interface{}, error) {
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "[") {
		if !strings.HasSuffix(s, "]") {
			return nil, fmt.Errorf("unterminated flow sequence")
		}
		inner := s[1 : len(s)-1]
		if strings.TrimSpace(inner) == "" {
			return []interface{}{}, nil
		}
		parts := splitFlow(inner)
		list := []interface{}{}
		for _, p := range parts {
			list = append(list, parseScalar(strings.TrimSpace(p)))
		}
		return list, nil
	}
	if strings.HasPrefix(s, "{") {
		if !strings.HasSuffix(s, "}") {
			return nil, fmt.Errorf("unterminated flow mapping")
		}
		inner := s[1 : len(s)-1]
		if strings.TrimSpace(inner) == "" {
			return map[string]interface{}{}, nil
		}
		parts := splitFlow(inner)
		m := map[string]interface{}{}
		for _, p := range parts {
			key, val, err := splitKeyValue(strings.TrimSpace(p))
			if err != nil {
				return nil, err
			}
			m[key] = parseScalar(strings.TrimSpace(val))
		}
		return m, nil
	}
	return parseScalar(s), nil
}

func splitFlow(s string) []string {
	parts := []string{}
	depth := 0
	inSingle := false
	inDouble := false
	start := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case '[', '{':
			if !inSingle && !inDouble {
				depth++
			}
		case ']', '}':
			if !inSingle && !inDouble {
				depth--
			}
		case ',':
			if depth == 0 && !inSingle && !inDouble {
				parts = append(parts, s[start:i])
				start = i + 1
			}
		}
	}
	parts = append(parts, s[start:])
	return parts
}
