    return val, err
}

func parseNode(lines []yamlLine, start, indent int) (interface{}, int, error) {
    if start >= len(lines) || lines[start].indent < indent {
        return nil, start, nil
    }
    if isSequenceLine(lines[start].text) {
        return parseSequence(lines, start, indent)
    }
    return parseMapping(lines, start, indent)
}

func isSequenceLine(text string) bool {
    return text == "-" || strings.HasPrefix(text, "- ")
}

func parseMapping(lines []yamlLine, start, indent int) (map[string]interface{}, int, error) {
    m := map[string]interface{}{}
    i := start
    for i < len(lines) {
        if lines[i].indent < indent {
            break
        }
        if lines[i].indent > indent {
            return nil, i, fmt.Errorf("unexpected indentation in mapping")
        }
        if isSequenceLine(lines[i].text) {
            break
        }

        key, val, err := splitKeyValue(lines[i].text)
        if err != nil {
            return nil, i, err
        }

        if val == "" {
            if i+1 < len(lines) {
                next := lines[i+1]
                if next.indent > indent {
                    child, next2, err := parseNode(lines, i+1, next.indent)
                    if err != nil {
                        return nil, 0, err
                    }
                    m[key] = child
                    i = next2
                    continue
                }
                if next.indent == indent && isSequenceLine(next.text) {
                    child, next2, err := parseSequence(lines, i+1, indent)
                    if err != nil {
                        return nil, 0, err
                    }
                    m[key] = child
                    i = next2
                    continue
                }
            }
            m[key] = nil
            i++
            continue
        }

        v, err := parseFlowOrScalar(val)
        if err != nil {
            return nil, 0, err
        }
        m[key] = v
        i++
    }
    return m, i, nil
}

func parseSequence(lines []yamlLine, start, indent int) ([]interface{}, int, error) {
    items := []interface{}{}
    i := start
    for i < len(lines) {
        if lines[i].indent < indent {
            break
        }
        if lines[i].indent > indent {
            return nil, i, fmt.Errorf("unexpected indentation in sequence")
        }
        if !isSequenceLine(lines[i].text) {
            break
        }

        content := strings.TrimSpace(strings.TrimPrefix(lines[i].text, "-"))
        if content == "" {
            if i+1 < len(lines) && lines[i+1].indent > indent {
                child, next, err := parseNode(lines, i+1, lines[i+1].indent)
                if err != nil {
                    return nil, 0, err
                }
                items = append(items, child)
                i = next
                continue
            }
            items = append(items, nil)
            i++
            continue
        }

        if strings.HasPrefix(content, "[") || strings.HasPrefix(content, "{") {
            v, err := parseFlow(content)
            if err != nil {
                return nil, 0, err
            }
            items = append(items, v)
            i++
            continue
        }

        if isMappingLine(content) {
            afterDash := strings.TrimPrefix(lines[i].text, "-")
            leading := len(afterDash) - len(strings.TrimLeft(afterDash, " "))
            effIndent := indent + 1 + leading
            sublines := []yamlLine{{indent: effIndent, text: content}}
            j := i + 1
            for j < len(lines) && lines[j].indent >= effIndent {
                sublines = append(sublines, lines[j])
                j++
            }
            child, _, err := parseMapping(sublines, 0, effIndent)
            if err != nil {
                return nil, 0, err
            }
            items = append(items, child)
            i = j
            continue
        }

        v, err := parseFlowOrScalar(content)
        if err != nil {
            return nil, 0, err
        }
        items = append(items, v)
        i++
    }
    return items, i, nil
}

func isMappingLine(text string) bool {
    _, _, err := splitKeyValue(text)
    return err == nil
}

func splitKeyValue(text string) (string, string, error) {
    inSingle := false
    inDouble := false
    for i := 0; i < len(text); i++ {
        c := text[i]
        switch c {
        case '\'':
            if !inDouble {
                inSingle = !inSingle
            }
        case '"':
            if !inSingle {
                inDouble = !inDouble
            }
        case ':':
            if !inSingle && !inDouble {
                if i+1 >= len(text) {
                    return parseScalar(strings.TrimSpace(text[:i])), "", nil
                }
                if text[i+1] == ' ' || text[i+1] == '\t' {
                    return parseScalar(strings.TrimSpace(text[:i])), strings.TrimSpace(text[i+1:]), nil
                }
            }
        }
    }
    return "", "", fmt.Errorf("expected mapping key: %q", text)
}

func parseFlowOrScalar(s string) (interface{}, error) {
    s = strings.TrimSpace(s)
    if strings.HasPrefix(s, "[") || strings.HasPrefix(s, "{") {
        return parseFlow(s)
    }
    return parseScalar(s), nil
}

func parseScalar(s string) string {
    s = strings.TrimSpace(s)
    if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
        if q, err := strconv.Unquote(s); err == nil {
            return q
        }
        return s[1 : len(s)-1]
    }
    if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
        return strings.ReplaceAll(s[1:len(s)-1], "''", "'")
    }
    return s
}

func stripComment(line string) string {
    inSingle := false
    inDouble := false
    for i := 0; i < len(line); i++ {
        c := line[i]
        switch c {
        case '\'':
            if !inDouble {
                inSingle = !inSingle
            }
        case '"':
            if !inSingle {
                inDouble = !inDouble
            }
        case '#':
            if !inSingle && !inDouble && (i == 0 || line[i-1] == ' ' || line[i-1] == '\t') {
                return line[:i]
            }
        }
    }
    return line
}

func parseFlow(s string) (interface{}, error) {
    s = strings.TrimSpace(s)
    if strings.HasPrefix(s, "[") {
        if !strings.HasSuffix(s, "]") {
            return nil, fmt.Errorf("unterminated flow sequence")
        }
        inner := s[1 : len(s)-1]
        if strings.TrimSpace(inner) == "" {
            return []interface{}{}, nil
        }
        parts := splitFlow(inner)
        list := []interface{}{}
        for _, p := range parts {
            v, err := parseFlowOrScalar(strings.TrimSpace(p))
            if err != nil {
                return nil, err
            }
            list = append(list, v)
        }
        return list, nil
    }
    if strings.HasPrefix(s, "{") {
        if !strings.HasSuffix(s, "}") {
            return nil, fmt.Errorf("unterminated flow mapping")
        }
        inner := s[1 : len(s)-1]
        if strings.TrimSpace(inner) == "" {
            return map[string]interface{}{}, nil
        }
        parts := splitFlow(inner)
        m := map[string]interface{}{}
        for _, p := range parts {
            key, val, err := splitKeyValue(strings.TrimSpace(p))
            if err != nil {
                return nil, err
            }
            v, err := parseFlowOrScalar(strings.TrimSpace(val))
            if err != nil {
                return nil, err
            }
            m[key] = v
        }
        return m, nil
    }
    return parseScalar(s), nil
}

func splitFlow(s string) []string {
    parts := []string{}
    depth := 0
    inSingle := false
    inDouble := false
    start := 0
    for i := 0; i < len(s); i++ {
        c := s[i]
        switch c {
        case '\'':
            if !inDouble {
                inSingle = !inSingle
            }
        case '"':
            if !inSingle {
                inDouble = !inDouble
            }
        case '[', '{':
            if !inSingle && !inDouble {
                depth++
            }
        case ']', '}':
            if !inSingle && !inDouble {
                depth--
            }
        case ',':
            if depth == 0 && !inSingle && !inDouble {
                parts = append(parts, s[start:i])
                start = i + 1
            }
        }
    }
    parts = append(parts, s[start:])
    return parts
}
