func Read(cfg config.InputConfig, dir string) ([]*record.Record, error) {
    switch cfg.Format {
    case "csv":
        return readCSV(cfg, dir)
    case "ndjson":
        return readNDJSON(cfg, dir)
    default:
        return nil, fmt.Errorf("input: unsupported format %q", cfg.Format)
    }
}

func readCSV(cfg config.InputConfig, dir string) ([]*record.Record, error) {
    path := config.ResolvePath(dir, cfg.Path)
    f, err := os.Open(path)
    if err != nil {
        return nil, fmt.Errorf("input: %v", err)
    }
    defer f.Close()

    r := csv.NewReader(f)
    r.FieldsPerRecord = 0
    r.TrimLeadingSpace = true

    header, err := r.Read()
    if err == io.EOF {
        return nil, fmt.Errorf("input: empty CSV file")
    }
    if err != nil {
        return nil, fmt.Errorf("input: %v", err)
    }

    records := []*record.Record{}
    rowNum := 0
    for {
        row, err := r.Read()
        if err == io.EOF {
            break
        }
        if err != nil {
            return nil, fmt.Errorf("input: row %d: %v", rowNum+2, err)
        }
        rowNum++

        if len(row) != len(header) {
            return nil, fmt.Errorf("input: row %d: expected %d fields got %d", rowNum+1, len(header), len(row))
        }

        rec := record.New()
        rec.InputRow = rowNum
        for i, col := range header {
            rec.Set(col, row[i])
        }
        records = append(records, rec)
    }

    return records, nil
}

func readNDJSON(cfg config.InputConfig, dir string) ([]*record.Record, error) {
    path := config.ResolvePath(dir, cfg.Path)
    f, err := os.Open(path)
    if err != nil {
        return nil, fmt.Errorf("input: %v", err)
    }
    defer f.Close()

    scanner := bufio.NewScanner(f)
    scanner.Buffer(make([]byte, 0, 1024*1024), 64*1024*1024)

    records := []*record.Record{}
    lineNum := 0
    recNum := 0
    for scanner.Scan() {
        lineNum++
        line := scanner.Text()
        if strings.TrimSpace(line) == "" {
            continue
        }

        rec, err := parseNDJSONLine(line, lineNum)
        if err != nil {
            return nil, fmt.Errorf("input: line %d: %v", lineNum, err)
        }
        recNum++
        rec.InputRow = recNum
        records = append(records, rec)
    }
    if err := scanner.Err(); err != nil {
        return nil, fmt.Errorf("input: %v", err)
    }

    return records, nil
}

func parseNDJSONLine(line string, lineNum int) (*record.Record, error) {
    dec := json.NewDecoder(strings.NewReader(line))

    t, err := dec.Token()
    if err != nil {
        return nil, fmt.Errorf("invalid JSON: %v", err)
    }
    if t != json.Delim('{') {
        return nil, fmt.Errorf("line is not a JSON object")
    }

    rec := record.New()
    for {
        t, err := dec.Token()
        if err == io.EOF {
            return nil, fmt.Errorf("unexpected end of object")
        }
        if err != nil {
            return nil, fmt.Errorf("invalid JSON: %v", err)
        }
        if t == json.Delim('}') {
            break
        }

        key, ok := t.(string)
        if !ok {
            return nil, fmt.Errorf("object key is not a string")
        }

        vt, err := dec.Token()
        if err != nil {
            return nil, fmt.Errorf("value for %q: %v", key, err)
        }
        s, ok := vt.(string)
        if !ok {
            return nil, fmt.Errorf("value for %q is not a JSON string", key)
        }
        rec.Set(key, s)
    }

    if dec.More() {
        return nil, fmt.Errorf("unexpected trailing content")
    }

    return rec, nil
}
