type Stats struct {
    Processed          int
    Emitted            int
    DroppedNonNumeric  int
    DroppedMissing     int
    missingReported    bool
}

type Stage interface {
    Apply(in []*record.Record, stderr io.Writer, strict bool, stats *Stats) ([]*record.Record, error)
}

func Build(rawStages []map[string]interface{}) ([]Stage, error) {
    stages := make([]Stage, 0, len(rawStages))
    for i, sm := range rawStages {
        typ, ok := getString(sm, "type")
        if !ok || typ == "" {
            return nil, fmt.Errorf("config: stage %d: type is required", i+1)
        }

        var st Stage
        var err error
        switch typ {
        case "filter":
            st, err = buildFilter(i+1, sm)
        case "project":
            st, err = buildProject(i+1, sm)
        case "sort":
            st, err = buildSort(i+1, sm)
        case "limit":
            st, err = buildLimit(i+1, sm)
        default:
            return nil, fmt.Errorf("config: stage %d: unknown stage type %q", i+1, typ)
        }
        if err != nil {
            return nil, err
        }
        stages = append(stages, st)
    }
    return stages, nil
}

type FilterStage struct {
    column string
    op     string
    value  string
}

func (s *FilterStage) Apply(in []*record.Record, stderr io.Writer, strict bool, stats *Stats) ([]*record.Record, error) {
    out := make([]*record.Record, 0, len(in))

    for _, r := range in {
        v, ok := r.Get(s.column)
        if !ok {
            stats.DroppedMissing++
            if !stats.missingReported {
                fmt.Fprintf(stderr, "flowctl: filter: missing column %s\n", s.column)
                stats.missingReported = true
            }
            if strict {
                return nil, fmt.Errorf("filter: missing column %s", s.column)
            }
            continue
        }

        keep := false
        switch s.op {
        case "==":
            keep = v == s.value
        case "!=":
            keep = v != s.value
        default:
            left, err := parseFloat(v)
            if err != nil {
                stats.DroppedNonNumeric++
                fmt.Fprintf(stderr, "flowctl: filter: drop non-numeric row %d\n", r.InputRow)
                if strict {
                    return nil, fmt.Errorf("filter: drop non-numeric row %d", r.InputRow)
                }
                continue
            }
            right, err := parseFloat(s.value)
            if err != nil {
                stats.DroppedNonNumeric++
                fmt.Fprintf(stderr, "flowctl: filter: drop non-numeric row %d\n", r.InputRow)
                if strict {
                    return nil, fmt.Errorf("filter: drop non-numeric row %d", r.InputRow)
                }
                continue
            }
            keep = compareFloats(left, s.op, right)
        }

        if keep {
            out = append(out, r)
        }
    }

    return out, nil
}

