    if !ok || column == "" {
        return nil, fmt.Errorf("config: stage %d: filter.where.column is required", idx)
    }

    op, ok := getString(where, "op")
    if !ok || op == "" {
        return nil, fmt.Errorf("config: stage %d: filter.where.op is required", idx)
    }
    switch op {
    case "==", "!=", "<", "<=", ">", ">=":
    default:
        return nil, fmt.Errorf("config: stage %d: filter.where.op is invalid", idx)
    }

    value, ok := getString(where, "value")
    if !ok {
