func buildProject(idx int, sm map[string]interface{}) (Stage, error) {
    colsRaw, ok := sm["columns"]
    if !ok {
        return nil, fmt.Errorf("config: stage %d: project.columns is required", idx)
    }
    list, ok := colsRaw.([]interface{})
    if !ok {
        return nil, fmt.Errorf("config: stage %d: project.columns must be a list", idx)
    }

    columns := make([]ProjectColumn, 0, len(list))
    seen := map[string]bool{}
    for j, item := range list {
        switch v := item.(type) {
        case string:
            if seen[v] {
                return nil, fmt.Errorf("config: stage %d: project output column %q duplicated", idx, v)
            }
            seen[v] = true
            columns = append(columns, ProjectColumn{Source: v, Target: v})
        case map[string]interface{}:
            name, ok := getString(v, "name")
            if !ok || name == "" {
                return nil, fmt.Errorf("config: stage %d: project column %d name is required", idx, j+1)
            }
            as, ok := getString(v, "as")
            if !ok || as == "" {
                return nil, fmt.Errorf("config: stage %d: project column %d as is required", idx, j+1)
            }
            if seen[as] {
                return nil, fmt.Errorf("config: stage %d: project output column %q duplicated", idx, as)
            }
            seen[as] = true
            columns = append(columns, ProjectColumn{Source: name, Target: as})
        default:
            return nil, fmt.Errorf("config: stage %d: project column %d must be a string or mapping", idx, j+1)
        }
    }

    return &ProjectStage{columns: columns}, nil
