func buildSort(idx int, sm map[string]interface{}) (Stage, error) {
    keysRaw, ok := sm["keys"]
    if !ok {
        return nil, fmt.Errorf("config: stage %d: sort.keys is required", idx)
    }
    list, ok := keysRaw.([]interface{})
    if !ok {
        return nil, fmt.Errorf("config: stage %d: sort.keys must be a list", idx)
    }

    keys := make([]SortKey, 0, len(list))
    for j, item := range list {
        km, ok := item.(map[string]interface{})
        if !ok {
            return nil, fmt.Errorf("config: stage %d: sort key %d must be a mapping", idx, j+1)
        }

        column, ok := getString(km, "column")
        if !ok || column == "" {
            return nil, fmt.Errorf("config: stage %d: sort key %d column is required", idx, j+1)
        }

        order, ok := getString(km, "order")
        if !ok || order == "" {
            order = "asc"
        }
        if order != "asc" && order != "desc" {
            return nil, fmt.Errorf("config: stage %d: sort key %d order must be asc or desc", idx, j+1)
        }

        as, ok := getString(km, "as")
        if !ok || as == "" {
            as = "string"
        }
        if as != "string" && as != "number" {
            return nil, fmt.Errorf("config: stage %d: sort key %d as must be string or number", idx, j+1)
        }

        keys = append(keys, SortKey{Column: column, Order: order, As: as})
    }

    return &SortStage{keys: keys}, nil
}

func buildLimit(idx int, sm map[string]interface{}) (Stage, error) {
    countRaw, ok := sm["count"]
    if !ok {
        return nil, fmt.Errorf("config: stage %d: limit.count is required", idx)
    }
    countStr, ok := countRaw.(string)
    if !ok {
        return nil, fmt.Errorf("config: stage %d: limit.count must be a non-negative integer", idx)
    }
    n, err := strconv.Atoi(countStr)
    if err != nil || n < 0 {
        return nil, fmt.Errorf("config: stage %d: limit.count must be a non-negative integer", idx)
    }

    return &LimitStage{count: n}, nil
}

func getString(m map[string]interface{}, key string) (string, bool) {
    v, ok := m[key]
    if !ok {
        return "", false
    }
    if s, ok := v.(string); ok {
        return s, true
    }
    return fmt.Sprintf("%v", v), true
}

func parseFloat(s string) (float64, error) {
    f, err := strconv.ParseFloat(s, 64)
    if err != nil {
        return 0, err
    }
    if math.IsNaN(f) || math.IsInf(f, 0) {
        return 0, fmt.Errorf("not a finite number")
    }
    return f, nil
}

func compareFloats(left float64, op string, right float64) bool {
    switch op {
    case "<":
        return left < right
    case "<=":
        return left <= right
    case ">":
        return left > right
    case ">=":
        return left >= right
    }
    return false
}
