    "example.com/flowctl/internal/record"
)

func Write(records []*record.Record, cfg config.OutputConfig, dir string) (int, error) {
    var buf bytes.Buffer

    for _, r := range records {
        if cfg.ColumnsPresent {
            writeObject(&buf, cfg.Columns, r)
        } else {
            writeObject(&buf, r.Order, r)
        }
        buf.WriteByte('\n')
    }

    if cfg.Path == "-" {
        if _, err := os.Stdout.Write(buf.Bytes()); err != nil {
            return 0, fmt.Errorf("output: %v", err)
        }
        return len(records), nil
    }

    full := config.ResolvePath(dir, cfg.Path)
    dirName := filepath.Dir(full)

    tmp, err := os.CreateTemp(dirName, ".flowctl-output-*")
    if err != nil {
        return 0, fmt.Errorf("output: %v", err)
    }

    if _, err := tmp.Write(buf.Bytes()); err != nil {
        tmp.Close()
        os.Remove(tmp.Name())
        return 0, fmt.Errorf("output: %v", err)
    }
    if err := tmp.Close(); err != nil {
        os.Remove(tmp.Name())
        return 0, fmt.Errorf("output: %v", err)
    }
    if err := os.Rename(tmp.Name(), full); err != nil {
        os.Remove(tmp.Name())
        return 0, fmt.Errorf("output: %v", err)
    }

    return len(records), nil
}

func writeObject(buf *bytes.Buffer, cols []string, r *record.Record) {
    buf.WriteByte('{')
    for i, col := range cols {
        if i > 0 {
            buf.WriteByte(',')
        }
        buf.WriteString(encodeJSONString(col))
        buf.WriteByte(':')
        val := ""
        if v, ok := r.Get(col); ok {
            val = v
        }
        buf.WriteString(encodeJSONString(val))
    }
    buf.WriteByte('}')
}

func encodeJSONString(s string) string {
    var b strings.Builder
    b.WriteByte('"')
    for i := 0; i < len(s); i++ {
        c := s[i]
        switch c {
        case '\\':
            b.WriteString("\\\\")
        case '"':
            b.WriteString("\\\"")
        case '\n':
            b.WriteString("\\n")
        case '\r':
            b.WriteString("\\r")
        case '\t':
            b.WriteString("\\t")
        default:
            if c < 0x20 {
                fmt.Fprintf(&b, "\\u%04x", c)
            } else {
                b.WriteByte(c)
            }
        }
    }
    b.WriteByte('"')
    return b.String()
}
