package pipeline

import (
    "os"

    "example.com/flowctl/internal/config"
    "example.com/flowctl/internal/input"
    "example.com/flowctl/internal/output"
    "example.com/flowctl/internal/stage"
)

func Run(cfg *config.Config) (*stage.Stats, error) {
    stats := &stage.Stats{}

    stages, err := stage.Build(cfg.Stages)
    if err != nil {
        return stats, err
    }

    records, err := input.Read(cfg.Input, cfg.Dir)
    if err != nil {
        return stats, err
    }
    stats.Processed = len(records)

    for _, st := range stages {
        records, err = st.Apply(records, os.Stderr, cfg.Strict, stats)
        if err != nil {
            return stats, err
        }
    }

    n, err := output.Write(records, cfg.Output, cfg.Dir)
    if err != nil {
        return stats, err
    }
    stats.Emitted = n

    return stats, nil
}
